// Decodifica o state Redis e expõe contexto para a IA
const state = JSON.parse($json.state_raw);
const payload = $('Parse Payload').first().json;
return [{
  json: {
    extracted_data: state.extracted_data,
    missing_fields: state.missing_fields,
    retry_count: state.retry_count || 0,
    context_text: payload.text,
    numero: payload.numero,
    instance: payload.instance,
    pushName: payload.pushName
  }
}];

// Mescla a resposta da IA com o state existente
const raw = $json.message?.content ?? $json;
let ai = {};
try {
  ai = typeof raw === 'object' ? raw : JSON.parse(String(raw).replace(/```json|```/g, '').trim());
} catch (e) {
  ai = {};
}

const state = $('Decode State').first().json;
const filled = Object.entries(ai).filter(([k, v]) => v !== null && v !== undefined && String(v).trim() !== '').map(([k]) => k);
const merged = { ...state.extracted_data };
filled.forEach(k => { merged[k] = ai[k]; });

const stillMissing = state.missing_fields.filter(f => !merged[f] || String(merged[f]).trim() === '');

return [{
  json: {
    ...merged,
    missing_fields: stillMissing,
    ai_understood: filled.length > 0,
    retry_count: state.retry_count + (filled.length > 0 ? 0 : 1),
    _from_response_branch: true
  }
}];

// Normaliza extração de imagem ou PDF + contexto do WhatsApp + caminho do Drive + define missing_fields

// === Configuração: campos obrigatórios para registrar ===
const REQUIRED = [
  'valor',
  'data_transacao',
  'id_transacao_e2e',
  'pagador_nome',
  'cliente_pedido',
  'vendedor'
];

const raw = $json.message?.content ?? $json;
let ai = {};
try {
  ai = typeof raw === 'object' && !raw.text ? raw : JSON.parse(String(raw).replace(/```json|```/g, '').trim());
} catch (e) {
  ai = { _parse_error: true };
}

const ctx = $('Parse Payload').first().json;

// Tenta pegar a URL do Drive de qualquer um dos dois nós (imagem ou pdf)
let drive_url = '';
let drive_id = '';
try { const d = $('Upload Drive (Imagem)').first().json; drive_url = d.webViewLink || ''; drive_id = d.id || ''; } catch(e) {}
if (!drive_url) {
  try { const d = $('Upload Drive (PDF)').first().json; drive_url = d.webViewLink || ''; drive_id = d.id || ''; } catch(e) {}
}

// O texto enviado junto da mídia pode já trazer cliente/vendedor (ex: "Siqueli @ Diogo Lourenço")
const caption = (ctx.text || '').trim();
let cliente_pedido = '';
let vendedor = '';
if (caption) {
  const m = caption.match(/^(.+?)\s*[@\-\/]\s*(.+)$/);
  if (m) {
    cliente_pedido = m[1].trim();
    vendedor = m[2].trim();
  }
}

const extracted = {
  // metadados WhatsApp
  timestamp: new Date().toISOString(),
  whatsapp_numero: ctx.numero,
  whatsapp_nome: ctx.pushName,
  arquivo_drive_url: drive_url,
  arquivo_drive_id: drive_id,
  // dados da transação
  tipo: ai.tipo || '',
  valor: ai.valor || '',
  data_transacao: ai.data_transacao || '',
  hora_transacao: ai.hora_transacao || '',
  pagador_nome: ai.pagador_nome || '',
  pagador_documento: ai.pagador_documento || '',
  pagador_banco: ai.pagador_banco || '',
  pagador_agencia_conta: ai.pagador_agencia_conta || '',
  beneficiario_nome: ai.beneficiario_nome || '',
  beneficiario_documento: ai.beneficiario_documento || '',
  beneficiario_chave_pix: ai.beneficiario_chave_pix || '',
  id_transacao_e2e: ai.id_transacao_e2e || '',
  numero_controle: ai.numero_controle || '',
  codigo_autenticacao: ai.codigo_autenticacao || '',
  // contexto GRD
  cliente_pedido,
  vendedor,
  observacoes: caption || '',
  status: 'Processado',
  raw_json: JSON.stringify(ai)
};

// Determina campos obrigatórios faltando
const missing_fields = REQUIRED.filter(f => !extracted[f] || String(extracted[f]).trim() === '');

return [{ json: { ...extracted, missing_fields, _from_media_branch: true } }];

// Detecta se já existe registro com mesmo e2e_id
const items = $input.all();
const existente = items.find(i => i.json && i.json.id_transacao_e2e);
const dadosNovos = $('Parse Extração').first().json;

if (existente) {
  return [{ json: { ...dadosNovos, duplicado: true, registro_anterior: existente.json } }];
}
return [{ json: { ...dadosNovos, duplicado: false } }];

