// Monta a pergunta dinâmica + prepara state pra salvar no Redis
const data = $json;
const missing = data.missing_fields;
const ai_understood = data.ai_understood !== false; // true por padrão (vindo da extração)
const retry = data.retry_count || 0;

const labels = {
  cliente_pedido: 'cliente do pedido (ex: Lá Belle, Asteca, Siqueli)',
  vendedor: 'vendedor responsável (ex: Marcus, Diogo)',
  valor: 'valor da transferência (ex: 198,45)',
  data_transacao: 'data da transferência (DD/MM/AAAA)',
  pagador_nome: 'quem fez o pagamento',
  beneficiario_nome: 'quem recebeu o pagamento',
  id_transacao_e2e: 'ID da transação (E2E)'
};

let pergunta;
if (!ai_understood && retry >= 1) {
  const list = missing.map((f, i) => `${i+1}. ${labels[f] || f}`).join('\n');
  pergunta = `🤔 Não entendi sua última resposta. Preciso ainda de:\n\n${list}\n\nResponde uma coisa por vez ou no formato "Cliente - Vendedor".`;
} else if (missing.length === 1) {
  pergunta = `📋 Quase lá! Me informa: *${labels[missing[0]] || missing[0]}*`;
} else {
  const list = missing.map((f, i) => `${i+1}. ${labels[f] || f}`).join('\n');
  const head = data.valor ? `📋 Recebi o comprovante de *R$ ${data.valor}*!` : '📋 Recebi o comprovante!';
  pergunta = `${head} Pra finalizar o registro, preciso de:\n\n${list}\n\nPode responder numa mensagem só (ex: "Lá Belle - Marcus").`;
}

// Limpa campos auxiliares pra salvar só dados
const { missing_fields, ai_understood: _au, retry_count: _rc, _from_media_branch, _from_response_branch, ...extracted_data } = data;

const state = {
  extracted_data,
  missing_fields: missing,
  retry_count: retry,
  asked_at: new Date().toISOString()
};

return [{
  json: {
    pergunta,
    state_json: JSON.stringify(state),
    numero: $('Parse Payload').first().json.numero,
    instance: $('Parse Payload').first().json.instance
  }
}];

